/**
 * Card 15A: edit traces for the offline timing replay. Timings and content ids only: the text
 * each id stands for is generated by `contentFor` and is never real source.
 */

export type TraceEventKind = 'open' | 'edit' | 'save' | 'undo-to';

export interface TraceEvent {
  /** Milliseconds from the start of the trace. */
  readonly atMs: number;
  readonly kind: TraceEventKind;
  /** Which content the file holds after the event; `undo-to` names an earlier one. */
  readonly contentId: string;
}

export interface EditTrace {
  readonly name: string;
  readonly events: readonly TraceEvent[];
}

/** Synthetic Java text for a content id: distinct per id, and nothing from a real file. */
export function contentFor(contentId: string): string {
  return `class Replay {\n  // content ${contentId}\n}\n`;
}

function edits(
  startMs: number,
  count: number,
  gapMs: number,
  prefix: string,
): TraceEvent[] {
  return Array.from({ length: count }, (_, i) => ({
    atMs: startMs + i * gapMs,
    kind: 'edit' as const,
    contentId: `${prefix}${i + 1}`,
  }));
}

/** 8 edits 400 ms apart, a 10 s pause, then 5 edits 600 ms apart. */
const BURST_PAUSE: EditTrace = {
  name: 'burst-pause',
  events: [...edits(0, 8, 400, 'a'), ...edits(12_800, 5, 600, 'b')],
};

/** An edit every 1.5 s for 30 s, which never leaves a 3 s pause. */
const SLOW_TYPING: EditTrace = {
  name: 'slow-typing',
  events: edits(0, 21, 1500, 's'),
};

/** Open A; after it is analysed, change to B, then undo back to A within 2 s. */
const UNDO_BACK: EditTrace = {
  name: 'undo-back',
  events: [
    { atMs: 0, kind: 'open', contentId: 'A' },
    { atMs: 14_000, kind: 'edit', contentId: 'B' },
    { atMs: 16_000, kind: 'undo-to', contentId: 'A' },
  ],
};

/** An edit then a save every 5 s for 60 s; each save repeats the content just edited. */
const SAVE_HEAVY: EditTrace = {
  name: 'save-heavy',
  events: Array.from({ length: 12 }, (_, i) => [
    { atMs: i * 5000, kind: 'edit' as const, contentId: `e${i + 1}` },
    { atMs: i * 5000 + 1000, kind: 'save' as const, contentId: `e${i + 1}` },
  ]).flat(),
};

/**
 * The edit timings of the BA-14 F5 run on 2026-11-28 (background log 04:30:36.931 to
 * 04:31:32.331, `Positive.java`), relative to the startup report. Content ids follow the
 * logged content hashes: `orig` is 29a0b30a, `c1` 663121f5, `c2` c3173ab9. Only the times and
 * the order are kept.
 */
const RECORDED_F5: EditTrace = {
  name: 'recorded-f5',
  events: [
    { atMs: 0, kind: 'open', contentId: 'orig' },
    { atMs: 19_065, kind: 'edit', contentId: 'c1' },
    { atMs: 53_940, kind: 'undo-to', contentId: 'orig' },
    { atMs: 55_400, kind: 'edit', contentId: 'c2' },
  ],
};

export const TRACES: readonly EditTrace[] = [
  BURST_PAUSE,
  SLOW_TYPING,
  UNDO_BACK,
  SAVE_HEAVY,
  RECORDED_F5,
];
